print(len(DECISIONS))

# COMMAND ----------

schema = ("facility_id string, source string, held_record_id string, vf_name string, ext_name string, decision string, "
          "chosen_record_id string, chosen_ext_name string, reason string")
df = spark.createDataFrame([tuple(r[c] for c in ["facility_id", "source", "held_record_id", "vf_name", "ext_name", "decision", "chosen_record_id", "chosen_ext_name", "reason"]) for r in DECISIONS], schema=schema)
df.createOrReplaceTempView("dec_in")
spark.sql(f"""
CREATE OR REPLACE TABLE workspace.vf_silver.ext_match_review_decisions
COMMENT 'One row per match that was held as ambiguous (Task D, pass 2, Rural Hospital Network) with the hand-review decision and reason. accepted = identity evidence at medium confidence; rejected = clear mismatch; left_for_review = unclear, still ambiguous and unused (notebook 19).'
AS SELECT *, '{DECIDED_BY}' AS decided_by, DATE'2026-11-22' AS decided_on FROM dec_in
""")

# COMMAND ----------

spark.sql("""
CREATE OR REPLACE VIEW workspace.vf_silver.ext_facility_matches_prereview AS
SELECT t.* FROM workspace.vf_silver.ext_facility_matches t
LEFT ANTI JOIN workspace.vf_silver.ext_facility_matches_pass2 p
  ON p.facility_id = t.facility_id AND p.source = t.source AND p.source_record_id = t.source_record_id
UNION ALL SELECT * FROM workspace.vf_silver.ext_facility_matches_pass2
""")

spark.sql("""
CREATE OR REPLACE TABLE workspace.vf_silver.ext_facility_matches_reviewed
COMMENT 'Hand-reviewed matches (notebook 19), same columns as Task D ext_facility_matches. accepted_medium or rejected only. Laid over Task D and pass 2 by the view ext_facility_matches_all.'
AS
SELECT d.facility_id, d.source, coalesce(d.chosen_record_id, d.held_record_id) AS source_record_id,
       coalesce(d.chosen_ext_name, m.ext_name) AS ext_name,
       coalesce(c.match_score, m.match_score) AS match_score, coalesce(c.name_sim, m.name_sim) AS name_sim, m.distance_km,
       'manual_review' AS match_method, m.matched_fields,
       CASE d.decision WHEN 'accepted' THEN 'accepted_medium' ELSE 'rejected' END AS match_status,
       concat('hand review 2026-11-22: ', d.reason) AS match_reason,
       m.source_type, m.source_ref,
       CASE d.decision WHEN 'accepted' THEN 'medium' ELSE 'low' END AS confidence
FROM workspace.vf_silver.ext_match_review_decisions d
JOIN workspace.vf_silver.ext_facility_matches_prereview m
  ON m.facility_id = d.facility_id AND m.source = d.source AND m.source_record_id = d.held_record_id
LEFT JOIN (SELECT facility_id, source, source_record_id, max(match_score) AS match_score, max(name_sim) AS name_sim
           FROM workspace.vf_silver.ext_facility_match_candidates GROUP BY 1, 2, 3) c
  ON c.facility_id = d.facility_id AND c.source = d.source AND c.source_record_id = d.chosen_record_id AND d.chosen_record_id <> d.held_record_id
WHERE d.decision IN ('accepted', 'rejected') AND d.source <> 'rural_hospital_network'
""")

spark.sql("""CREATE OR REPLACE VIEW workspace.vf_silver.ext_facility_matches_all AS
SELECT t.* FROM workspace.vf_silver.ext_facility_matches_prereview t
LEFT ANTI JOIN (SELECT facility_id, source, held_record_id AS rid FROM workspace.vf_silver.ext_match_review_decisions WHERE decision <> 'left_for_review'
                UNION SELECT facility_id, source, chosen_record_id FROM workspace.vf_silver.ext_match_review_decisions WHERE decision = 'accepted') x
  ON x.facility_id = t.facility_id AND x.source = t.source AND x.rid = t.source_record_id
UNION ALL SELECT * FROM workspace.vf_silver.ext_facility_matches_reviewed""")

# COMMAND ----------

# MAGIC %md
# MAGIC ## Checks

# COMMAND ----------

spark.sql("""
CREATE OR REPLACE TABLE workspace.vf_silver.ext_match_review_checks AS
SELECT 1 AS n, 'every held match has exactly one decision' AS check_name,
       concat((SELECT count(*) FROM workspace.vf_silver.ext_match_review_decisions), ' decisions vs ',
              (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_prereview WHERE match_status = 'ambiguous') + (SELECT count(*) FROM workspace.vf_silver.ext_rhn_facility_matches WHERE match_status = 'ambiguous'), ' held') AS value,
       (SELECT count(*) FROM workspace.vf_silver.ext_match_review_decisions) = (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_prereview WHERE match_status = 'ambiguous') + (SELECT count(*) FROM workspace.vf_silver.ext_rhn_facility_matches WHERE match_status = 'ambiguous')
       AND (SELECT count(*) FROM workspace.vf_silver.ext_match_review_decisions d LEFT ANTI JOIN (SELECT facility_id, source, source_record_id FROM workspace.vf_silver.ext_facility_matches_prereview WHERE match_status = 'ambiguous' UNION ALL SELECT facility_id, source, source_record_id FROM workspace.vf_silver.ext_rhn_facility_matches WHERE match_status = 'ambiguous') h ON h.facility_id = d.facility_id AND h.source = d.source AND h.source_record_id = d.held_record_id) = 0 AS passed
UNION ALL SELECT 2, 'every decision has a reason', CAST(count(*) AS STRING), count(*) = 0 FROM workspace.vf_silver.ext_match_review_decisions WHERE reason IS NULL OR length(reason) < 15
UNION ALL SELECT 3, 'Task D row count unchanged by the view (rows in all = rows before review)',
       concat((SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_all), ' vs ', (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_prereview)),
       (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_all) = (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_prereview)
UNION ALL SELECT 4, 'still ambiguous in the view = left for review (excluding Rural Hospital Network)',
       concat((SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_all WHERE match_status = 'ambiguous'), ' vs ', (SELECT count(*) FROM workspace.vf_silver.ext_match_review_decisions WHERE decision = 'left_for_review' AND source <> 'rural_hospital_network')),
       (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_all WHERE match_status = 'ambiguous') = (SELECT count(*) FROM workspace.vf_silver.ext_match_review_decisions WHERE decision = 'left_for_review' AND source <> 'rural_hospital_network')
UNION ALL SELECT 5, 'no facility has two accepted records from one source', CAST(count(*) AS STRING), count(*) = 0
       FROM (SELECT facility_id, source FROM workspace.vf_silver.ext_facility_matches_all WHERE match_status LIKE 'accepted%' AND source IN ('nabh', 'eraktkosh', 'wikidata') GROUP BY 1, 2 HAVING count(*) > 1)
UNION ALL SELECT 6, 'no reviewed record is accepted for two facilities', CAST(count(*) AS STRING), count(*) = 0
       FROM (SELECT a.source, a.source_record_id FROM workspace.vf_silver.ext_facility_matches_all a
             JOIN workspace.vf_silver.ext_facility_matches_reviewed r ON r.source = a.source AND r.source_record_id = a.source_record_id AND r.match_status = 'accepted_medium'
             WHERE a.match_status LIKE 'accepted%' GROUP BY 1, 2 HAVING count(DISTINCT a.facility_id) > 1)
UNION ALL SELECT 7, 'no reviewed match is rated high', CAST(count(*) AS STRING), count(*) = 0 FROM workspace.vf_silver.ext_facility_matches_reviewed WHERE match_status = 'accepted_high' OR confidence = 'high'
UNION ALL SELECT 8, 'Task D and pass 2 tables still hold their ambiguous rows (not overwritten)',
       CAST((SELECT count(*) FROM workspace.vf_silver.ext_facility_matches WHERE match_status = 'ambiguous') + (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_pass2 WHERE match_status = 'ambiguous') AS STRING),
       (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches WHERE match_status = 'ambiguous') + (SELECT count(*) FROM workspace.vf_silver.ext_facility_matches_pass2 WHERE match_status = 'ambiguous') = 286
""")
display(spark.sql("SELECT * FROM workspace.vf_silver.ext_match_review_checks ORDER BY n"))

# COMMAND ----------

out = {
    "checks": [r.asDict() for r in spark.sql("SELECT * FROM workspace.vf_silver.ext_match_review_checks ORDER BY n").collect()],
    "decisions": [r.asDict() for r in spark.sql("SELECT source, decision, count(*) n FROM workspace.vf_silver.ext_match_review_decisions GROUP BY 1, 2 ORDER BY 1, 2").collect()],
    "view_status": [r.asDict() for r in spark.sql("SELECT source, match_status, count(*) n FROM workspace.vf_silver.ext_facility_matches_all WHERE match_status <> 'rejected' GROUP BY 1, 2 ORDER BY 1, 2").collect()],
}
dbutils.notebook.exit(json.dumps(out, default=str))
